      hookId: Schema.String,
      token: Schema.String,
    });
    const RELAY_HOOK_PATH = "/v1/hooks/:endpointKey/:hookId/:token";
    const relayHookEndpoint = { params: RelayHookParams } as const;
    const RelayHooksGroup = HttpApiGroup.make("hooks")
